# Package 2c: dict_vale(). Contract: dev/design-2c.md "dict_vale(...)", rules 4.7.2, 4.7.4,
# P10, 9.3.1, C9-C14. Every file is written in a temp project. Helpers: helper-2c.R.

VALE_HEADER <- c(
  "# Generated by weft::dict_vale() from dict.yml. Do not edit: change the",
  "# `avoid:` fields in dict.yml and run weft::dict_vale() again."
)

vale_text <- function(swap, level = "warning", header = VALE_HEADER) {
  c(header,
    "extends: substitution",
    "message: \"Use '%s' instead of '%s' (the project dictionary's spelling).\"",
    paste0("level: ", level),
    "ignorecase: false",
    "swap:",
    paste0("  ", swap))
}

FIXTURE_SWAP <- c(
  "'minimum sample-size': 'minimum sample size'",
  "'northern catchment': 'Northern catchment'",
  "'min sample size': 'minimum sample size'",
  "'Nth\\. catchment': 'Northern catchment'"
)

# a project holding the fixture as dict.yml, with the working folder in it
vale_proj <- function(files = list(), env = parent.frame()) {
  dir <- c2_proj(c(list(dict.yml = c2_fixture_lines()), files), env)
  withr::local_dir(dir, .local_envir = env)
  dir
}

abs_path <- function(dir, rel = "styles/Weft/Terms.yml") {
  normalizePath(file.path(dir, rel), mustWork = FALSE)
}

HINT <- function(dir, styles = "styles", style = "Weft") {
  sprintf("Vale uses this rule when .vale.ini, at %s, sets StylesPath = %s and lists %s in BasedOnStyles.",
          dir, styles, style)
}

read_rule <- function(p) readLines(p, warn = FALSE, encoding = "UTF-8")

test_that("2c vale: the rule from the fixture is exactly the contract's text, UTF-8, LF, final newline (4.7.2, C10, C11)", {
  dir <- vale_proj()
  suppressMessages(dict_vale(dict = NULL))
  p <- abs_path(dir)
  expect_true(file.exists(p))
  expect_identical(read_rule(p), vale_text(FIXTURE_SWAP))
  expect_identical(c2_bytes(p), charToRaw(paste0(paste(vale_text(FIXTURE_SWAP), collapse = "\n"), "\n")))
})

test_that("2c vale: the messages are 'weft will write', 'Wrote:' and the .vale.ini hint, and the path comes back invisibly (4.7.2, C12)", {
  dir <- vale_proj()
  r <- c2_says(dict_vale())
  p <- abs_path(dir)
  expect_identical(r$msgs, c(
    sprintf("weft will write %s: a Vale substitution rule with 4 avoided spelling(s) from dict.yml.", p),
    sprintf("Wrote: %s", p),
    HINT(dir)))
  expect_identical(r$value, p)
  expect_false(r$visible)
})

test_that("2c vale: it says what it will write before the file exists (P10, K9)", {
  dir <- vale_proj()
  seen <- NULL
  c2_says(dict_vale(), on_first = function() {
    seen <<- file.exists(abs_path(dir)) || dir.exists(file.path(dir, "styles"))
  })
  expect_false(is.null(seen))
  expect_false(seen)
})

test_that("2c vale: a dictionary passed as dict gives the same rule, the header naming its file's basename (4.7.2)", {
  dir <- vale_proj(list(`terms-src.yml` = c2_fixture_lines()))
  d <- read_dict(file.path(dir, "terms-src.yml"))
  unlink(file.path(dir, "dict.yml"))
  suppressMessages(dict_vale(d))
  expect_identical(read_rule(abs_path(dir)),
                   vale_text(FIXTURE_SWAP, header = sub("from dict.yml", "from terms-src.yml", VALE_HEADER, fixed = TRUE)))
})

test_that("2c vale: it writes only the rule file and its folders, and never .vale.ini (C12, P10)", {
  dir <- vale_proj()
  before <- c2_tree(dir)
  suppressMessages(dict_vale())
  expect_setequal(setdiff(c2_tree(dir), before), c("styles", "styles/Weft", "styles/Weft/Terms.yml"))
  expect_false(file.exists(file.path(dir, ".vale.ini")))
})

test_that("2c vale: a second run says 'Nothing to change' and writes nothing (4.7.2 step 3)", {
  dir <- vale_proj()
  suppressMessages(dict_vale())
  p <- abs_path(dir)
  old <- as.POSIXct("2001-02-03 04:05:06", tz = "UTC")
  Sys.setFileTime(p, old)
  before <- c2_bytes(p)
  r <- c2_says(dict_vale())
  expect_identical(r$msgs[1], sprintf("Nothing to change: %s is up to date.", p))
  expect_identical(r$msgs[-1], HINT(dir))
  expect_identical(r$value, character())
  expect_false(r$visible)
  expect_identical(c2_bytes(p), before)
  expect_equal(as.numeric(file.mtime(p)), as.numeric(old))
})

test_that("2c vale: a .vale.ini listing the style in BasedOnStyles gets no hint (step 5)", {
  dir <- vale_proj(list(`.vale.ini` = c("StylesPath = styles", "", "[*.md]", "BasedOnStyles = Vale, Weft")))
  r <- c2_says(dict_vale())
  expect_length(r$msgs, 2L)
  expect_false(grepl("Vale uses this rule", r$all, fixed = TRUE))
  r2 <- c2_says(dict_vale())
  expect_identical(r2$msgs, sprintf("Nothing to change: %s is up to date.", abs_path(dir)))
})

test_that("2c vale: a .vale.ini that does not list the style (or only a longer name) still gets the hint (step 5)", {
  dir <- vale_proj(list(`.vale.ini` = c("StylesPath = styles", "[*.md]", "BasedOnStyles = Vale, Weftish")))
  r <- c2_says(dict_vale())
  expect_true(HINT(dir) %in% r$msgs)
  expect_identical(readLines(file.path(dir, ".vale.ini")),
                   c("StylesPath = styles", "[*.md]", "BasedOnStyles = Vale, Weftish"))
})

test_that("2c vale: the hint names the path's style folder and the folder above it, relative to the root (step 5)", {
  dir <- vale_proj()
  r <- c2_says(dict_vale(path = "lint/Prose/Words.yml"))
  expect_true(HINT(dir, styles = "lint", style = "Prose") %in% r$msgs)
  expect_true(file.exists(abs_path(dir, "lint/Prose/Words.yml")))
})

test_that("2c vale C14: a relative path is under the project root, not the working folder", {
  dir <- vale_proj(list(`_weft.yml` = "digits: 1", `chapters/x.txt` = "x"))
  withr::local_dir(file.path(dir, "chapters"))
  suppressMessages(dict_vale(dict = read_dict(file.path(dir, "dict.yml"))))
  expect_true(file.exists(abs_path(dir)))
  expect_false(dir.exists(file.path(dir, "chapters", "styles")))
})

test_that("2c vale C14: an absolute path is kept (4.7.2)", {
  dir <- vale_proj()
  other <- c2_proj()
  p <- file.path(other, "styles", "Weft", "Terms.yml")
  r <- c2_says(dict_vale(path = p))
  expect_true(file.exists(p))
  expect_identical(r$value, normalizePath(p, mustWork = FALSE))
  expect_false(dir.exists(file.path(dir, "styles")))
})

test_that("2c vale C13: a file the function did not write is a weft_tool_error and is left alone (step 2)", {
  dir <- vale_proj(list(`styles/Weft/Terms.yml` = c("extends: existence", "message: mine", "tokens: [x]")))
  p <- abs_path(dir)
  before <- c2_bytes(p)
  e <- c2_err(dict_vale())
  c2_expect_cond(e, "weft_tool_error")
  c2_expect_msg(e, sprintf("dict_vale(): %s exists and was not written by dict_vale(); nothing was written. Move it, or give another `path`.", p))
  expect_identical(c2_bytes(p), before)
})

test_that("2c vale C13: a file written earlier by dict_vale() but out of date is replaced (steps 3 and 4)", {
  dir <- vale_proj(list(`styles/Weft/Terms.yml` = c(VALE_HEADER, "extends: substitution", "swap:", "  'old': 'new'")))
  p <- abs_path(dir)
  r <- c2_says(dict_vale())
  expect_identical(r$msgs[1:2], c(
    sprintf("weft will write %s: a Vale substitution rule with 4 avoided spelling(s) from dict.yml.", p),
    sprintf("Wrote: %s", p)))
  expect_identical(read_rule(p), vale_text(FIXTURE_SWAP))
})

test_that("2c vale C13: with no avoid anywhere and weft's own file present, it says, removes it and returns the path (step 1)", {
  plain <- readLines(testthat::test_path("_dict", "dict.yml"))   # before the directory changes
  dir <- vale_proj()
  suppressMessages(dict_vale())
  p <- abs_path(dir)
  expect_true(file.exists(p))
  writeLines(plain, file.path(dir, "dict.yml"))
  r <- c2_says(dict_vale())
  expect_identical(r$msgs, c(
    sprintf("weft will remove %s: dict.yml has no avoid: spellings now.", p),
    sprintf("Removed: %s", p)))
  expect_identical(r$value, p)
  expect_false(r$visible)
  expect_false(file.exists(p))
})

test_that("2c vale C13: with no avoid and no file, it says there is no rule to write and returns character() (step 1)", {
  dir <- c2_proj(list(dict.yml = readLines(testthat::test_path("_dict", "dict.yml"))))
  withr::local_dir(dir)
  before <- c2_tree(dir)
  r <- c2_says(dict_vale())
  expect_identical(r$msgs, "dict.yml has no avoid: spellings, so there is no rule to write.")
  expect_identical(r$value, character())
  expect_false(r$visible)
  expect_identical(c2_tree(dir), before)
})

test_that("2c vale C13: with no avoid, an authored file at path is neither removed nor an error (step 1)", {
  dir <- c2_proj(list(dict.yml = readLines(testthat::test_path("_dict", "dict.yml")),
                      `styles/Weft/Terms.yml` = c("extends: existence", "tokens: [x]")))
  withr::local_dir(dir)
  p <- abs_path(dir)
  before <- c2_bytes(p)
  r <- c2_says(dict_vale())
  expect_identical(r$msgs, "dict.yml has no avoid: spellings, so there is no rule to write.")
  expect_identical(r$value, character())
  expect_identical(c2_bytes(p), before)
})

test_that("2c vale: level goes into the file, and a level that is not suggestion, warning or error is a weft_tool_error (4.7.2)", {
  dir <- vale_proj()
  suppressMessages(dict_vale(level = "error"))
  expect_identical(read_rule(abs_path(dir)), vale_text(FIXTURE_SWAP, level = "error"))
  unlink(file.path(dir, "styles"), recursive = TRUE)
  suppressMessages(dict_vale(level = "suggestion"))
  expect_true("level: suggestion" %in% read_rule(abs_path(dir)))
  before <- c2_tree(dir)
  unlink(file.path(dir, "styles"), recursive = TRUE)
  before <- c2_tree(dir)
  for (bad in list("loud", NA_character_, c("error", "warning"), 1)) {
    e <- c2_err(dict_vale(level = bad))
    c2_expect_cond(e, "weft_tool_error")
    c2_expect_msg(e, "dict_vale(): `level` must be one of suggestion, warning or error.")
  }
  expect_identical(c2_tree(dir), before)
})

test_that("2c vale: a path that is not a rule file inside a style folder is a weft_tool_error and nothing is written (4.7.2)", {
  dir <- vale_proj()
  before <- c2_tree(dir)
  for (bad in c("Terms.yml", "styles/Terms.txt", "Weft/Terms.yml", "styles/Weft/Terms.yaml")) {
    e <- c2_err(dict_vale(path = bad))
    c2_expect_cond(e, "weft_tool_error")
    c2_expect_msg(e, "dict_vale(): `path` must name a rule file inside a style folder, as styles/Weft/Terms.yml; got `",
                  bad)
  }
  expect_identical(c2_tree(dir), before)
  e2 <- c2_err(dict_vale(path = c("a/b/c.yml", "a/b/d.yml")))
  c2_expect_cond(e2, "weft_tool_error")
})

test_that("2c vale: a dict with no dict.yml at the root and one that is not a dictionary are weft_tool_errors naming dict_vale() (Errors)", {
  dir <- c2_proj()
  withr::local_dir(dir)
  e <- c2_err(dict_vale())
  c2_expect_cond(e, "weft_tool_error")
  c2_expect_msg(e, "dict_vale(): there is no dict.yml at ", "use_dictionary().")
  e2 <- c2_err(dict_vale(dict = list(a = 1)))
  c2_expect_cond(e2, "weft_tool_error")
  c2_expect_msg(e2, "dict_vale(): `dict` must be a dictionary, as read_dict() returns; got list.")
  expect_identical(c2_tree(dir), character())
})

test_that("2c vale C9: a dict.yml with a problem raises its weft_dict_error and nothing is written", {
  dir <- c2_proj(list(dict.yml = c(
    "a: {value: Alpha, type: string, definition: x, avoid: [Beta]}",
    "b: {value: Beta gamma, type: string, definition: x}")))
  withr::local_dir(dir)
  before <- c2_tree(dir)
  e <- c2_err(dict_vale())
  c2_expect_cond(e, "weft_dict_error")
  c2_expect_msg(e, "(rule 4.7.4)")
  expect_identical(c2_tree(dir), before)
})

test_that("2c vale: regular-expression characters in a spelling are escaped in the key; the value is as written (4.7.2)", {
  specials <- "a.b (c)d"
  dir <- c2_proj(list(dict.yml = c(
    "a: {value: Canon, type: string, definition: x, avoid: [\"a.b (c)d\"]}",
    "b: {value: Other, type: string, definition: x, avoid: [\"x+y*z?q\", \"p|q\", \"k[k]{2}k\", \"s^s$s\", \"back\\\\slash\"]}")))
  withr::local_dir(dir)
  suppressMessages(dict_vale())
  lines <- read_rule(abs_path(dir))
  swap <- lines[(which(lines == "swap:") + 1):length(lines)]
  expect_true("  'a\\.b \\(c\\)d': 'Canon'" %in% swap)
  expect_true("  'x\\+y\\*z\\?q': 'Other'" %in% swap)
  expect_true("  'p\\|q': 'Other'" %in% swap)
  expect_true("  'k\\[k\\]\\{2\\}k': 'Other'" %in% swap)
  expect_true("  's\\^s\\$s': 'Other'" %in% swap)
  expect_true("  'back\\\\slash': 'Other'" %in% swap)
})

test_that("2c vale: a single quote in a spelling or in the canonical spelling is doubled (4.7.2)", {
  dir <- c2_proj(list(dict.yml = c(
    "a: {value: \"Bob's text\", type: string, definition: x, avoid: [\"it's\", \"Bobs text\"]}")))
  withr::local_dir(dir)
  suppressMessages(dict_vale())
  lines <- read_rule(abs_path(dir))
  expect_true("  'it''s': 'Bob''s text'" %in% lines)
  expect_true("  'Bobs text': 'Bob''s text'" %in% lines)
})

test_that("2c vale C11: spellings sort by unescaped length, longest first, equal lengths by radix (4.7.2)", {
  dir <- c2_proj(list(dict.yml = c(
    "a: {value: Zed, type: string, definition: x, avoid: [\"b b\", \"a a\", \"C C\", \"a.a.a\", \"q\"]}")))
  withr::local_dir(dir)
  suppressMessages(dict_vale())
  lines <- read_rule(abs_path(dir))
  swap <- lines[(which(lines == "swap:") + 1):length(lines)]
  expect_identical(swap, c("  'a\\.a\\.a': 'Zed'", "  'C C': 'Zed'", "  'a a': 'Zed'",
                           "  'b b': 'Zed'", "  'q': 'Zed'"))
})

test_that("2c vale: the canonical spelling of an entry with a term is its term, of a string with none its value (C1)", {
  dir <- c2_proj(list(dict.yml = c(
    "n: {value: 5, type: number, term: the count, avoid: [cnt], definition: x}",
    "s: {value: Plain, type: string, avoid: [plain], definition: x}",
    "t: {value: Plain2, type: string, term: Termed, avoid: [plain2], definition: x}")))
  withr::local_dir(dir)
  suppressMessages(dict_vale())
  lines <- read_rule(abs_path(dir))
  expect_true("  'cnt': 'the count'" %in% lines)
  expect_true("  'plain': 'Plain'" %in% lines)
  expect_true("  'plain2': 'Termed'" %in% lines)
})

test_that("2c vale: a non-ASCII spelling is written as UTF-8 (4.7.2)", {
  dir <- c2_proj(list(dict.yml = "a: {value: \"Café au lait\", type: string, definition: x, avoid: [\"Cafe au lait\"]}"))
  withr::local_dir(dir)
  suppressMessages(dict_vale())
  lines <- read_rule(abs_path(dir))
  expect_true("  'Cafe au lait': 'Café au lait'" %in% lines)
})
